public class Partial_with_TriageGen1Test {

    @Test
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstanceUTC());
        try {
            partial.with(null, 10);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The field type must not be null", e.getMessage());
        }
    }












